Item.method_code:
/*
    帳票マスタ・開達書式用
    BeforeとAfter用のメソッドで１セット動作
    OnBeforeVersionとOnAfterVersionの両方で値を取得しないと前後の値の収集ができない
    
    h4_ChangeWfForDATFormatのマイナーチェンジ版
    開達書式の場合、資料分類によって、WFを切り替える

*/
Innovator inn = this.getInnovator();

const string EXPTest = "EXPTest";//List h4_category の値
const string NormalWF = "h4_DATFormatWF";
const string EXPWF ="h4_DATFormatEXPWF";

const string DATFormat = "h4_DATFormat";
const string DATMaster = "h4_DATMaster";

string beforeMajorRev = (string)RequestState["h4_DatBeforeMajorRev"];

Item currentItem = this.apply("getItemLastVersion");
var thisType = currentItem.getType();
var thisState = currentItem.getProperty("state","");
var thisCategory =  currentItem.getProperty("h4_category","");

//更新後のアイテムのメジャーrevision確認
Item newItem = inn.newItem(thisType, "get");
newItem.setProperty("config_id", this.getProperty("config_id"));
newItem.setProperty("is_current", "1");
newItem.setAttribute("select", "id,major_rev");
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    newItem = newItem.apply();
}

string currRev = newItem.getProperty("major_rev");

//同じなら無視
if (beforeMajorRev == currRev)
{
    return this;
}



// メジャーrevisionが異なる＝メジャーrevision作成時処理開始
//更新直後のアイテムID
var thisId = newItem.getID();

//開達書式の場合、紐づけWFを確認
var isNowEXP = false;
if(thisType == DATFormat)
{
    var beforeCategory = inn.newItem(DATFormat,"get");
    beforeCategory.setID(thisId);
    beforeCategory.setAttribute("h4_category","");
    using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
    {
        beforeCategory = beforeCategory.apply();
        if(beforeCategory.isError())
        {
            //エラー
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
        }
    }
    //EXPかそうでないかの変更チェック
    if(thisCategory == EXPTest){ isNowEXP = true;}
}


// WF変更 切り替え先のWFIDを取得
var useWF = NormalWF;
if(isNowEXP){useWF = EXPWF;}
Item workflowMap = inn.newItem("Workflow Map", "get");
workflowMap.setAttribute("select", "id");
workflowMap.setProperty("name", useWF);
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    workflowMap = workflowMap.apply();
    if(workflowMap.isError())
    {
        //エラー
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
    }
}
string mapId = workflowMap.getProperty("id");


//WF紐づけ
Item workflowProcess = newItem.instantiateWorkflow(mapId);
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    workflowProcess = workflowProcess.apply("startWorkflow");
    if(workflowProcess.isError())
    {
        //エラー
        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
    }
}

return this;
